107	/// Encodes decoded module data back into `.beam` container bytes.
108	///
109	/// The returned bytes decode to a [`ParsedModule`] equal to `module` (atoms,
110	/// instructions, imports, exports, lambdas, literals, strings, lines) when
111	/// loaded against the same `atom_table`.
112	pub fn encode_module(
113	    module: &ParsedModule,
114	    atom_table: &AtomTable,
115	) -> Result<Vec<u8>, EncodeError> {
116	    let encoder = AtomEncoder::new(&module.atoms, atom_table, module.type_chunk.is_some());
117	
118	    // Canonical chunk order.
119	    //
120	    // `AtU8`, `Code`, `ImpT`, `ExpT` and `StrT` are emitted UNCONDITIONALLY,
121	    // even when empty. Our own loader treats an absent optional chunk as empty
122	    // (`load.rs` reads `StrT` with `unwrap_or_default`), so omitting them round
123	    // trips perfectly through beamr and is invisible to our own suite — but
124	    // OTP's `beam_disasm` hard-requires all five and refuses the module with
125	    // `{missing_chunk, _, "StrT"}` (or `"ExpT"` / `"ImpT"`) when one is absent.
126	    // A module nobody else's tools can read is a module we cannot investigate
127	    // with the ecosystem's instruments, and that cost has already been paid
128	    // once: a 7,828-module sweep silently skipped our module because
129	    // `beam_disasm` would not open it.
130	    //
131	    // The required set was measured, not assumed — each chunk was stripped in
132	    // turn from a working module and fed to `beam_disasm` (OTP 29). `Attr`,
133	    // `CInf`, `Dbgi`, `Docs`, `Line`, `LocT`, `Meta` and `Type` are genuinely
134	    // optional and stay conditional. `FunT` is likewise not required. `LitT`
135	    // remains conditional: stripping it from a module that HAS literals leaves
136	    // dangling references, so that arm of the experiment is a confound rather
137	    // than evidence that it is mandatory.
138	    let mut chunks: Vec<(&[u8; 4], Vec<u8>)> = vec![
139	        (b"AtU8", encode_atom_chunk(&module.atoms, &encoder)?),
140	        (b"Code", encode_code_chunk(&module.instructions, &encoder)?),
141	        (b"ImpT", encode_import_chunk(&module.imports, &encoder)?),
142	        (b"ExpT", encode_export_chunk(&module.exports, &encoder)?),
143	    ];
144	    if !module.lambdas.is_empty() {
145	        chunks.push((b"FunT", encode_lambda_chunk(&module.lambdas, &encoder)?));
146	    }
147	    if let Some(literal_chunk) = encode_literal_chunk(&module.literals, &encoder)? {
148	        chunks.push((b"LitT", literal_chunk));
149	    }
150	    chunks.push((b"StrT", encode_string_chunk(&module.string_table)));
151	    if !module.line_info.is_empty() {
152	        chunks.push((b"Line", encode_line_chunk(&module.line_info)?));
153	    }
154	    // VERBATIM, never rebuilt: typed-register operands in the Code chunk index
155	    // into these bytes, and only the identical bytes keep those indices valid
156	    // (#95). The chunk is opaque to beamr's own loader on purpose.
157	    if let Some(type_chunk) = &module.type_chunk {
158	        chunks.push((b"Type", type_chunk.clone()));
159	    }
160	
161	    Ok(frame_container(&chunks))
162	}
