13	categories = ["asynchronous", "development-tools"]
14	
15	[lints]
16	workspace = true
17	
18	[dependencies]
19	aion-core = { version = "0.17.0", path = "../aion-core" }
20	aion-package = { version = "0.17.0", path = "../aion-package" }
21	# The harness-integration SDK — the TRAIT ONLY (`AgentHarness`/`AgentSession`).
22	# The worker drives ANY harness generically through this seam; it must NEVER
23	# depend on a concrete adapter (`aion-integration-norn`) or on `norn` itself
24	# (the §3A.4 no-norn-in-platform invariant). The concrete harness is injected by
25	# the binary composition root (aion-cli), never named here.
26	aion-integrations = { version = "0.17.0", path = "../aion-integrations" }
27	aion-proto = { version = "0.17.0", path = "../aion-proto", features = ["generated"] }
28	# Transcript events carry a producer-clock emission instant; the worker stamps
29	# one per line of command output it streams.
30	chrono = { workspace = true }
31	dashmap = { workspace = true }
32	tokio = { workspace = true, features = ["full"] }
33	tonic = { workspace = true }
34	prost = { workspace = true }
35	thiserror = { workspace = true }
36	serde = { workspace = true, features = ["derive"] }
37	serde_json = { workspace = true }
38	schemars = { workspace = true }
39	tracing = { workspace = true }
40	futures = { workspace = true }
41	async-trait.workspace = true
42	tokio-stream = { workspace = true }
43	uuid = { workspace = true }
44	hostname = { workspace = true }
45	# Cross-node worker transport over the liminal bus (LSUB-1). OPTIONAL and OFF by
46	# default: a default worker build links only the gRPC transport and never pulls
47	# liminal-sdk (nor its transitive beamr distribution). Enabled only by the
48	# `liminal-transport` feature. Resolved from crates.io (liminal-sdk); the default
49	# `std` feature carries the real TCP push client and the canonical wire codec.
50	liminal-sdk = { workspace = true, optional = true }
51	# Liminal core protocol types (LSUB-L2): the worker builds a
52	# `liminal::protocol::WorkerRegistration` and self-registers in-band via
53	# `PushClient::connect_with_registration`. Already in the dependency graph
54	# transitively (liminal-sdk depends on it); named directly only so the worker can
55	# construct the wire registration type. Optional, enabled only by
56	# `liminal-transport`.
57	liminal = { workspace = true, optional = true }
58	
59	[target.'cfg(unix)'.dependencies]
60	# Safe process-group signalling for worker-owned command containment. The shared
61	# adapter is consumed by both `aion worker shell` and worker harnesses.
62	nix = { version = "0.30", features = ["process", "signal"] }
63	
64	[features]
65	default = []
66	# Liminal worker transport: a `LiminalActivityWorker` that connects a server-push
67	# client, receives `DispatchRequest` frames, executes via the existing activity
68	# registry, and replies with a correlated `DispatchResponse`. OFF by default so a
69	# default worker build is byte-identical and never links liminal-sdk.
70	liminal-transport = ["dep:liminal-sdk", "dep:liminal"]
71	
72	[dev-dependencies]
73	tokio = { workspace = true, features = ["full", "test-util"] }
74	tokio-stream = { workspace = true, features = ["net"] }
